/* Mandatory accessibility rule */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --card-border: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --primary: #38bdf8;
  --primary-hover: #0284c7;
  --success: #22c55e;
  --danger: #ef4444;
  --focus-ring: #f59e0b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.game-card {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 1rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 480px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.game-header {
  text-align: center;
}

.game-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.game-instructions {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.score-box {
  background-color: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--card-border);
  border-radius: 0.5rem;
  padding: 0.75rem;
  text-align: center;
  display: flex;
  flex-direction: column;
}

.score-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.target-display {
  text-align: center;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--card-border);
  border-radius: 0.75rem;
  padding: 1rem;
}

.target-label {
  display: block;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.rgb-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: 0.025em;
}

.swatches-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  justify-content: center;
}

.swatch {
  aspect-ratio: 1 / 1;
  width: 100%;
  border-radius: 0.75rem;
  border: 3px solid rgba(255, 255, 255, 0.1);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  outline: none;
}

.swatch:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.35);
  border-color: rgba(255, 255, 255, 0.4);
}

.swatch:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
}

.swatch:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 4px;
}

.swatch:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

.feedback-banner {
  min-height: 1.75rem;
  text-align: center;
  font-weight: 600;
  font-size: 1rem;
  transition: color 0.2s ease;
}

.feedback-banner.correct {
  color: var(--success);
}

.feedback-banner.incorrect {
  color: var(--danger);
}

.controls-footer {
  display: flex;
  justify-content: center;
}

.action-btn {
  background-color: var(--primary);
  color: #0f172a;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 0.5rem;
  padding: 0.75rem 1.75rem;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.15s ease;
}

.action-btn:hover {
  background-color: var(--primary-hover);
  color: #ffffff;
}

.action-btn:active {
  transform: scale(0.97);
}

.action-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .game-card {
    padding: 1.25rem;
    gap: 1.25rem;
  }

  .game-title {
    font-size: 1.5rem;
  }

  .rgb-code {
    font-size: 1.15rem;
  }

  .swatches-container {
    gap: 0.6rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // State variables
  let currentStreak = 0;
  let bestStreak = 0;
  let targetColor = { r: 0, g: 0, b: 0 };
  let isRoundOver = false;

  // DOM references
  const currentScoreEl = document.getElementById('current-score');
  const bestScoreEl = document.getElementById('best-score');
  const rgbCodeEl = document.getElementById('rgb-code');
  const feedbackEl = document.getElementById('feedback');
  const restartBtn = document.getElementById('restart-btn');
  const swatchButtons = [
    document.getElementById('swatch-0'),
    document.getElementById('swatch-1'),
    document.getElementById('swatch-2')
  ];

  // Load best streak from localStorage if accessible
  try {
    const storedBest = localStorage.getItem('pixel_best_streak');
    if (storedBest !== null) {
      bestStreak = parseInt(storedBest, 10) || 0;
      bestScoreEl.textContent = bestStreak;
    }
  } catch (e) {
    // Gracefully fallback when storage is restricted
  }

  // Helper: generates random integer in range [min, max]
  function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  // Helper: generates a random RGB color object
  function generateRandomColor() {
    return {
      r: getRandomInt(0, 255),
      g: getRandomInt(0, 255),
      b: getRandomInt(0, 255)
    };
  }

  // Helper: calculate Euclidean color distance to guarantee distractors are distinct
  function colorDistance(c1, c2) {
    return Math.sqrt(
      Math.pow(c1.r - c2.r, 2) +
      Math.pow(c1.g - c2.g, 2) +
      Math.pow(c1.b - c2.b, 2)
    );
  }

  // Generate a distinct distractor color
  function generateDistractor(target, existingColors) {
    let candidate;
    let attempts = 0;
    do {
      candidate = generateRandomColor();
      attempts++;
      const farFromTarget = colorDistance(target, candidate) > 50;
      const farFromOthers = existingColors.every(c => colorDistance(c, candidate) > 35);
      if (farFromTarget && farFromOthers) {
        break;
      }
    } while (attempts < 50);
    return candidate;
  }

  function formatRgbString(c) {
    return `rgb(${c.r}, ${c.g}, ${c.b})`;
  }

  // Initialize a new round
  function startRound() {
    isRoundOver = false;
    feedbackEl.textContent = '';
    feedbackEl.className = 'feedback-banner';

    targetColor = generateRandomColor();
    rgbCodeEl.textContent = formatRgbString(targetColor);

    const distractors = [];
    distractors.push(generateDistractor(targetColor, []));
    distractors.push(generateDistractor(targetColor, distractors));

    const swatchesData = [targetColor, distractors[0], distractors[1]];
    // Fisher-Yates shuffle
    for (let i = swatchesData.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [swatchesData[i], swatchesData[j]] = [swatchesData[j], swatchesData[i]];
    }

    swatchButtons.forEach((btn, index) => {
      const color = swatchesData[index];
      btn.style.backgroundColor = formatRgbString(color);
      btn.dataset.r = color.r;
      btn.dataset.g = color.g;
      btn.dataset.b = color.b;
      btn.disabled = false;
      btn.setAttribute('aria-label', `Color swatch option ${index + 1}`);
    });
  }

  // Handle swatch selection
  function handleSwatchClick(e) {
    if (isRoundOver) return;

    const btn = e.currentTarget;
    const r = parseInt(btn.dataset.r, 10);
    const g = parseInt(btn.dataset.g, 10);
    const b = parseInt(btn.dataset.b, 10);

    const isCorrect = r === targetColor.r && g === targetColor.g && b === targetColor.b;

    if (isCorrect) {
      currentStreak += 1;
      if (currentStreak > bestStreak) {
        bestStreak = currentStreak;
        try {
          localStorage.setItem('pixel_best_streak', bestStreak.toString());
        } catch (err) {}
        bestScoreEl.textContent = bestStreak;
      }
      currentScoreEl.textContent = currentStreak;
      feedbackEl.textContent = 'Correct! Next round starting...';
      feedbackEl.className = 'feedback-banner correct';

      isRoundOver = true;
      swatchButtons.forEach(button => button.disabled = true);

      setTimeout(() => {
        startRound();
      }, 800);
    } else {
      isRoundOver = true;
      feedbackEl.textContent = `Game Over! That was incorrect. Final streak: ${currentStreak}.`;
      feedbackEl.className = 'feedback-banner incorrect';
      currentStreak = 0;
      currentScoreEl.textContent = currentStreak;
      swatchButtons.forEach(button => button.disabled = true);
      restartBtn.focus();
    }
  }

  // Event listeners
  swatchButtons.forEach(btn => {
    btn.addEventListener('click', handleSwatchClick);
  });

  restartBtn.addEventListener('click', () => {
    currentStreak = 0;
    currentScoreEl.textContent = currentStreak;
    startRound();
  });

  // Kick off the initial round
  startRound();
});
